<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import type { Trade } from '../types'
import { money, number, percent, date } from '../format'
import StatusBadge from './StatusBadge.vue'
const props = defineProps<{ trades: Trade[]; open?: boolean }>(); const emit = defineEmits<{ select: [trade: Trade] }>()
const filter = ref('Todos'); const page=ref(0); const rows = computed(() => props.trades.filter(t => filter.value === 'Todos' || t.profile === filter.value))
const visible=computed(()=>rows.value.slice(page.value*25,(page.value+1)*25)); watch([filter,()=>props.trades],()=>{page.value=0})
</script>
<template><section class="card table-card"><div class="panel-heading"><div><h3>{{ open ? 'Operaciones abiertas' : 'Operaciones cerradas' }}</h3><p>{{ rows.length }} registros · clasificación visible por operación</p></div><select v-model="filter" aria-label="Filtrar perfil"><option>Todos</option><option>EURUSD_R1</option><option>EURUSD_R5</option><option>EURUSD_R10</option></select></div><div class="table-scroll" tabindex="0" aria-label="Operaciones con procedencia y costos"><table><caption class="sr-only">Operaciones: comisiones y resultados pendientes identificados</caption><thead><tr><th>Perfil / origen</th><th>Símbolo / lado</th><th>Cantidad</th><th>Entrada</th><th>{{ open ? 'Actual' : 'Salida' }}</th><th>Stop / target</th><th>P&L bruto</th><th>P&L neto {{ open ? 'estimado' : '' }}</th><th>Comisión / evidencia</th><th>Spread / slippage</th><th>Prob. / EV</th><th>Régimen</th><th>Hora / duración</th><th>Estado</th><th>Detalle</th></tr></thead><tbody><tr v-for="t in visible" :key="`${t.profile}:${t.id}`"><td><b>{{ t.profile }}</b><StatusBadge :value="t.classification === 'BROKER_PAPER_EXECUTION' ? 'IBKR PAPER' : t.classification" :tone="t.classification === 'BROKER_EXECUTION' || t.classification === 'BROKER_PAPER_EXECUTION' ? 'warn' : 'neutral'" /></td><td>{{ t.symbol }}<small>{{ t.direction }}</small></td><td>{{ number(t.quantity) }}</td><td>{{ number(t.entry, 5) }}</td><td>{{ number(open ? t.currentPrice : t.exit, 5) }}</td><td>{{ number(t.stop, 5) }}<small>{{ number(t.target, 5) }}</small></td><td>{{ money(t.grossPnl) }}</td><td :class="{ negative: (t.netPnl ?? 0) < 0 }">{{ money(t.netPnl) }}</td><td>{{ money(t.commission) }}<small>{{ t.commissionStatus }}</small></td><td>{{ money(t.spread) }}<small>{{ money(t.slippage) }}</small></td><td>{{ percent(t.probability) }}<small>{{ money(t.expectedValue) }}</small></td><td>{{ t.regime }}</td><td>{{ date(open ? t.openedAt : t.closedAt) }}<small>{{ t.durationSeconds == null ? 'Duración UNKNOWN' : `${number(t.durationSeconds,0)} s` }}</small></td><td><StatusBadge :value="t.outcome ?? t.status" /><small>{{ open ? t.protection : t.exitCategory }}</small></td><td><button class="text-button" @click="emit('select', t)">Ver</button></td></tr><tr v-if="!rows.length"><td colspan="15" class="empty-cell"><strong>{{ open ? 'No hay posiciones registradas' : 'Sin operaciones completadas' }}</strong><span>Una señal NO_TRADE no cuenta como operación. No se generan entradas para llenar esta tabla.</span></td></tr></tbody></table></div><div v-if="rows.length>25" class="table-pagination"><span>{{ page*25+1 }}–{{ Math.min((page+1)*25,rows.length) }} de {{ rows.length }}</span><button class="secondary-button" :disabled="page===0" @click="page--">Anterior</button><button class="secondary-button" :disabled="(page+1)*25>=rows.length" @click="page++">Siguiente</button></div></section></template>
